import fs from 'node:fs';
import { initializeApp } from 'firebase/app';
import { getAuth, signInAnonymously } from 'firebase/auth';
import { getFirestore, doc, getDoc } from 'firebase/firestore';
const source=fs.readFileSync('js/firebase-config.js','utf8');
const pick=n=>(source.match(new RegExp(n+':\\s*"([^"]+)"'))||[,''])[1];
const app=initializeApp({apiKey:pick('apiKey'),authDomain:pick('authDomain'),projectId:pick('projectId'),storageBucket:pick('storageBucket'),messagingSenderId:pick('messagingSenderId'),appId:pick('appId')});
await signInAnonymously(getAuth(app));
const db=getFirestore(app);
const s=await getDoc(doc(db,'tipos_entrada','E5ir1Ptc4IN1zPUtEMrk'));
console.log('TIPO_ENTRADA',JSON.stringify(s.data()));
process.exit(0);